eps","quadriceps"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"VASTUS_LATERALIS","label":"Vasto lateral","muscleGroup":"QUADRICEPS","role":"SECONDARY","aliases":["quadríceps"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"VASTUS_MEDIALIS","label":"Vasto medial","muscleGroup":"QUADRICEPS","role":"SECONDARY","aliases":["quadríceps"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"VASTUS_INTERMEDIUS","label":"Vasto intermédio","muscleGroup":"QUADRICEPS","role":"SECONDARY","aliases":["vasto intermediário","quadríceps"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"GLUTEUS_MAXIMUS","label":"Glúteo máximo","muscleGroup":"GLUTES","role":"SECONDARY","aliases":["glúteos","gluteus maximus"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"BICEPS_FEMORIS","label":"Bíceps femoral — cabeça longa","muscleGroup":"HAMSTRINGS","role":"SECONDARY","aliases":["posteriores da coxa","isquiotibiais"],"regions":[{"id":"BICEPS_FEMORIS_LONG_HEAD","label":"Cabeça longa do bíceps femoral","aliases":["bíceps femoral cabeça longa"]}],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"SEMITENDINOSUS","label":"Semitendíneo","muscleGroup":"HAMSTRINGS","role":"SECONDARY","aliases":["semitendinoso","semitendinosus","posteriores da coxa","isquiotibiais"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"SEMIMEMBRANOSUS","label":"Semimembranáceo","muscleGroup":"HAMSTRINGS","role":"SECONDARY","aliases":["semimembranoso","semimembranosus","posteriores da coxa","isquiotibiais"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"GLUTEUS_MEDIUS","label":"Glúteo médio","muscleGroup":"HIP_ABDUCTORS","role":"SECONDARY","aliases":["gluteus medius","abdutores do quadril"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"PECTORALIS_MAJOR","label":"Peitoral maior — lado de apoio","muscleGroup":"CHEST","role":"SECONDARY","aliases":["peitoral","peito"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER","ACE_SINGLE_ROW"]},{"id":"DELTOID_ANTERIOR","label":"Deltoide anterior — lado de apoio","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["ombro anterior"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"TRICEPS_BRACHII","label":"Tríceps braquial — lado de apoio","muscleGroup":"TRICEPS","role":"SECONDARY","aliases":["tríceps","extensores do cotovelo"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"SERRATUS_ANTERIOR","label":"Serrátil anterior","muscleGroup":"BACK","role":"SECONDARY","aliases":["serratus anterior","controle escapular"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OYAMA_2010"]}],"sources":[{"id":"FENWICK_2009","title":"Fenwick, Brown & McGill — Comparison of Different Rowing Exercises (2009)","url":"https://pubmed.ncbi.nlm.nih.gov/19197209/","limitation":"Sete homens; remada curvada em pé, invertida e unilateral no cabo. Biomecânica/EMG aguda e amostra pequena; não comprova hipertrofia, segurança universal ou equivalência à remada apoiada com halter."},{"id":"OPENSTAX_UPPER","title":"OpenStax Anatomy and Physiology 2e — Muscles of the Pectoral Girdle and Upper Limbs","url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/11-5-muscles-of-the-pectoral-girdle-and-upper-limbs","limitation":"Anatomia funcional: adução/extensão do ombro, flexão do cotovelo, controle escapular e pegada. Papéis não medidos no estudo e estabilização do tronco são inferências anatômicas/editoriais, sem quantificação nesta variação."},{"id":"ARNOLD_2010","title":"Arnold et al. — A Model of the Lower Limb for Analysis of Human Movement","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC2903973/","limitation":"Anatomia funcional das pernas. Sustentação da postura nesta remada é inferência anatômica, não intensidade EMG medida."},{"id":"ACE_SINGLE_ROW","title":"ACE Exercise Library — Single-arm Row","url":"https://www.acefitness.org/resources/everyone/exercise-library/126/single-arm-row/","limitation":"Guia técnico para apoio de mão/joelho e pé oposto, pegada neutra e tronco firme. Não é medição EMG nem comprova correção de assimetrias."},{"id":"PADOVAN_SCAPULA_2026","title":"Padovan et al. — Scapular positions in the seated row (2026; online 24/12/2025)","url":"https://doi.org/10.3390/jfmk11010006","limitation":"14 homens treinados, remada sentada, 8RM, quatro repetições; HD-sEMG por fase, sem medir a cinemática do avatar ou hipertrofia. Movimento livre e escápulas fixas são condições distintas. Extrapolação para remada em pé/unilateral é anatômica e editorial."},{"id":"OYAMA_2010","title":"Oyama et al. — Three-dimensional scapular and clavicular kinematics during retraction exercises","url":"https://doi.org/10.2519/jospt.2010.3018","limitation":"Adultos jovens saudáveis, seis exercícios de retração; rotação externa, rotação superior e inclinação posterior escapular, retração/depressão clavicular. Quantidades variam por tarefa. As amplitudes do avatar são ilustrativas, não valores medidos nesses exercícios."},{"id":"VASCONCELOS_2023","title":"Vasconcelos et al. — Grip position and shoulder-abduction angle in the seated cable row","url":"https://doi.org/10.47206/ijsc.v3i1.190","limitation":"11 homens e 10 mulheres recreacionalmente treinados; testes isométricos/dinâmicos, pegadas pronada/supinada/neutra e abdução 30/60/90°. Maior abdução favoreceu trapézio/deltoide posterior nos registros; menor abdução, dorsal. Transferência para barra livre é inferência, não medição ou isolamento."}],"notes":"Dorsal, redondo maior, trapézio médio e romboides do lado do halter como principais. Lado oposto e braços estabilizam o apoio: peitoral, deltoide anterior e tríceps secundários no lado plantado. Tronco e pernas sustentam a postura. Lateralidade descrita na variante/notas porque o contrato não persiste papel por lado. A animação mostra um lado por ciclo; repetir do outro depois. Mão apoiada tem extensão de punho e orientação própria, não a rotação do antebraço inteiro. O rig não articula dedos individualmente. Sem rotação do tronco, isolamento, intensidade medida ou alegação de corrigir assimetrias. Fenwick comparou unilateral no cabo, não este halter apoiado: não transferir cargas, EMG ou conclusões clínicas. Demais participantes são inferência anatômica qualitativa. Cores ilustrativas; neutro não significa inativo. Revisão escapular: Na volta, permita que as escápulas se afastem sobre o tórax; ao puxar, aproxime-as de modo coordenado com os braços, mantendo a coluna estável. Serrátil anterior participa do controle, em destaque secundário ilustrativo. Escápulas têm controles independentes e pesos anatômicos; a trajetória não é produzida apenas pelo cotovelo. Ângulos não são medidas individuais.","instructions":{"description":"Remada unilateral com um halter, mão e joelho do lado oposto apoiados em um banco plano.","setup":"Apoie uma mão e o joelho do mesmo lado no banco e mantenha o outro pé no chão. Segure o halter com a mão livre, palma voltada para o corpo, coluna alinhada e quadril estável.","execution":"Conduza o cotovelo do braço livre em direção ao quadril, trazendo o halter para perto do tronco. Faça uma pausa breve e desça com controle até alongar o braço, sem girar o corpo ou retirar os apoios. Na volta, permita que as escápulas se afastem sobre o tórax; ao puxar, aproxime-as de modo coordenado com os braços, mantendo a coluna estável. O lado da mão apoiada permanece estável; o movimento escapular acompanha o lado do halter.","tips":"O banco deve ficar firme. Não eleve excessivamente o ombro nem force o cotovelo muito acima das costas. A animação demonstra um lado; depois repita do outro. O lado de apoio também estabiliza o corpo. Cores ilustrativas, sem medir ativação, EMG ou esforço."}}'::jsonb,"updatedAt"=NOW() WHERE id='00000000-0000-4000-8000-000000000138' AND "ownerUserId" IS NULL AND name='Remada Unilateral com Halteres' AND "anatomyReview"='{"version":"2026-11-16.1","reviewedAt":"2026-11-16T12:55:00.000Z","variant":"Remada unilateral com um halter em pegada neutra, mão e joelho opostos apoiados em banco plano e pé do lado do halter no chão.","aliases":["remada unilateral com halteres","remada unilateral com halter","serrote com halter"],"participants":[{"id":"LATISSIMUS_DORSI","label":"Latíssimo do dorso","muscleGroup":"BACK","role":"PRIMARY","aliases":["dorsal","grande dorsal","latissimus dorsi"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"TERES_MAJOR","label":"Redondo maior","muscleGroup":"BACK","role":"PRIMARY","aliases":["teres major"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"TRAPEZIUS","label":"Trapézio","muscleGroup":"BACK","role":"PRIMARY","aliases":["trapézio médio","trapézio inferior","trapezius"],"regions":[{"id":"TRAPEZIUS_TRANSVERSE","label":"Porção média do trapézio","aliases":["trapézio médio","porção transversa"]},{"id":"TRAPEZIUS_DESCENDING","label":"Porção superior do trapézio","aliases":["trapézio superior"]},{"id":"TRAPEZIUS_ASCENDING","label":"Porção inferior do trapézio","aliases":["trapézio inferior"]}],"emphasizedRegionIds":["TRAPEZIUS_TRANSVERSE"],"sourceIds":["OPENSTAX_UPPER"]},{"id":"RHOMBOIDS","label":"Romboides","muscleGroup":"BACK","role":"PRIMARY","aliases":["romboide maior","romboide menor"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"DELTOID_POSTERIOR","label":"Deltoide posterior","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["ombro posterior"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"INFRASPINATUS","label":"Infraespinal","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["infraespinhoso","manguito rotador"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"BICEPS_BRACHII","label":"Bíceps braquial","muscleGroup":"BICEPS","role":"SECONDARY","aliases":["bíceps"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"BRACHIALIS","label":"Braquial","muscleGroup":"BICEPS","role":"SECONDARY","aliases":["braquial anterior"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"BRACHIORADIALIS","label":"Braquiorradial","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["braquiorradialis"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"FLEXOR_DIGITORUM_SUPERFICIALIS","label":"Flexor superficial dos dedos","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["pegada"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"FLEXOR_DIGITORUM_PROFUNDUS","label":"Flexor profundo dos dedos","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["pegada"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"FLEXOR_CARPI_ULNARIS","label":"Flexor ulnar do carpo","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["punho"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"EXTENSOR_CARPI_RADIALIS_BREVIS","label":"Extensor radial curto do carpo","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["punho"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"ERECTOR_SPINAE","label":"Eretores da coluna","muscleGroup":"BACK","role":"SECONDARY","aliases":["eretor da espinha","estabilizadores do tronco"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"RECTUS_ABDOMINIS","label":"Reto abdominal","muscleGroup":"CORE","role":"SECONDARY","aliases":["abdômen","abdominais"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"EXTERNAL_OBLIQUE","label":"Oblíquo externo","muscleGroup":"CORE","role":"SECONDARY","aliases":["oblíquos"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"RECTUS_FEMORIS","label":"Reto femoral","muscleGroup":"QUADRICEPS","role":"SECONDARY","aliases":["quadríceps","quadriceps"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"VASTUS_LATERALIS","label":"Vasto lateral","muscleGroup":"QUADRICEPS","role":"SECONDARY","aliases":["quadríceps"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"VASTUS_MEDIALIS","label":"Vasto medial","muscleGroup":"QUADRICEPS","role":"SECONDARY","aliases":["quadríceps"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"VASTUS_INTERMEDIUS","label":"Vasto intermédio","muscleGroup":"QUADRICEPS","role":"SECONDARY","aliases":["vasto intermediário","quadríceps"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"GLUTEUS_MAXIMUS","label":"Glúteo máximo","muscleGroup":"GLUTES","role":"SECONDARY","aliases":["glúteos","gluteus maximus"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"BICEPS_FEMORIS","label":"Bíceps femoral — cabeça longa","muscleGroup":"HAMSTRINGS","role":"SECONDARY","aliases":["posteriores da coxa","isquiotibiais"],"regions":[{"id":"BICEPS_FEMORIS_LONG_HEAD","label":"Cabeça longa do bíceps femoral","aliases":["bíceps femoral cabeça longa"]}],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"SEMITENDINOSUS","label":"Semitendíneo","muscleGroup":"HAMSTRINGS","role":"SECONDARY","aliases":["semitendinoso","semitendinosus","posteriores da coxa","isquiotibiais"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"SEMIMEMBRANOSUS","label":"Semimembranáceo","muscleGroup":"HAMSTRINGS","role":"SECONDARY","aliases":["semimembranoso","semimembranosus","posteriores da coxa","isquiotibiais"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"GLUTEUS_MEDIUS","label":"Glúteo médio","muscleGroup":"HIP_ABDUCTORS","role":"SECONDARY","aliases":["gluteus medius","abdutores do quadril"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"PECTORALIS_MAJOR","label":"Peitoral maior — lado de apoio","muscleGroup":"CHEST","role":"SECONDARY","aliases":["peitoral","peito"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER","ACE_SINGLE_ROW"]},{"id":"DELTOID_ANTERIOR","label":"Deltoide anterior — lado de apoio","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["ombro anterior"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"TRICEPS_BRACHII","label":"Tríceps braquial — lado de apoio","muscleGroup":"TRICEPS","role":"SECONDARY","aliases":["tríceps","extensores do cotovelo"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]}],"sources":[{"id":"FENWICK_2009","title":"Fenwick, Brown & McGill — Comparison of Different Rowing Exercises (2009)","url":"https://pubmed.ncbi.nlm.nih.gov/19197209/","limitation":"Sete homens; remada curvada em pé, invertida e unilateral no cabo. Biomecânica/EMG aguda e amostra pequena; não comprova hipertrofia, segurança universal ou equivalência à remada apoiada com halter."},{"id":"OPENSTAX_UPPER","title":"OpenStax Anatomy and Physiology 2e — Muscles of the Pectoral Girdle and Upper Limbs","url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/11-5-muscles-of-the-pectoral-girdle-and-upper-limbs","limitation":"Anatomia funcional: adução/extensão do ombro, flexão do cotovelo, controle escapular e pegada. Papéis não medidos no estudo e estabilização do tronco são inferências anatômicas/editoriais, sem quantificação nesta variação."},{"id":"ARNOLD_2010","title":"Arnold et al. — A Model of the Lower Limb for Analysis of Human Movement","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC2903973/","limitation":"Anatomia funcional das pernas. Sustentação da postura nesta remada é inferência anatômica, não intensidade EMG medida."},{"id":"ACE_SINGLE_ROW","title":"ACE Exercise Library — Single-arm Row","url":"https://www.acefitness.org/resources/everyone/exercise-library/126/single-arm-row/","limitation":"Guia técnico para apoio de mão/joelho e pé oposto, pegada neutra e tronco firme. Não é medição EMG nem comprova correção de assimetrias."}],"notes":"Dorsal, redondo maior, trapézio médio e romboides do lado do halter como principais. Lado oposto e braços estabilizam o apoio: peitoral, deltoide anterior e tríceps secundários no lado plantado. Tronco e pernas sustentam a postura. Lateralidade descrita na variante/notas porque o contrato não persiste papel por lado. A animação mostra um lado por ciclo; repetir do outro depois. Mão apoiada tem extensão de punho e orientação própria, não a rotação do antebraço inteiro. O rig não articula dedos individualmente. Sem rotação do tronco, isolamento, intensidade medida ou alegação de corrigir assimetrias. Fenwick comparou unilateral no cabo, não este halter apoiado: não transferir cargas, EMG ou conclusões clínicas. Demais participantes são inferência anatômica qualitativa. Cores ilustrativas; neutro não significa inativo.","instructions":{"description":"Remada unilateral com um halter, mão e joelho do lado oposto apoiados em um banco plano.","setup":"Apoie uma mão e o joelho do mesmo lado no banco e mantenha o outro pé no chão. Segure o halter com a mão livre, palma voltada para o corpo, coluna alinhada e quadril estável.","execution":"Conduza o cotovelo do braço livre em direção ao quadril, trazendo o halter para perto do tronco. Faça uma pausa breve e desça com controle até alongar o braço, sem girar o corpo ou retirar os apoios.","tips":"O banco deve ficar firme. Não eleve excessivamente o ombro nem force o cotovelo muito acima das costas. A animação demonstra um lado; depois repita do outro. O lado de apoio também estabiliza o corpo. Cores ilustrativas, sem medir ativação, EMG ou esforço."}}'::jsonb AND (SELECT string_agg(m.role::text || ':' || m."muscleGroup"::text,'|' ORDER BY m.role::text || ':' || m."muscleGroup"::text) FROM "ExerciseMuscle" m WHERE m."exerciseId"="Exercise".id)='PRIMARY:BACK|SECONDARY:BICEPS|SECONDARY:CHEST|SECONDARY:CORE|SECONDARY:FOREARMS|SECONDARY:GLUTES|SECONDARY:HAMSTRINGS|SECONDARY:HIP_